CREATE TABLE developer_webhook_subscriptions(
 id TEXT PRIMARY KEY,app_id TEXT NOT NULL,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,destination_id TEXT NOT NULL,fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64),
 topics TEXT NOT NULL CHECK(topics IN('["projects.changed"]','["exports.changed"]','["exports.changed","projects.changed"]')),enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 1000000000),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
 UNIQUE(app_id,destination_id),UNIQUE(id,tenant_id,workspace_id,environment,app_env),FOREIGN KEY(app_id,tenant_id,workspace_id,environment,app_env) REFERENCES developer_apps(id,tenant_id,workspace_id,environment,app_env)
);
CREATE TABLE developer_webhook_sources(topic TEXT NOT NULL CHECK(topic IN('projects.changed','exports.changed','webhook.test')),source_id TEXT NOT NULL,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL REFERENCES workspaces(id),environment TEXT NOT NULL,app_env TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 1000000000),last_event_id TEXT NOT NULL,PRIMARY KEY(topic,source_id));
CREATE TABLE developer_webhook_events(
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,topic TEXT NOT NULL,source_id TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 1000000000),payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=32768 AND json_valid(payload)),created_at TEXT NOT NULL,version INTEGER NOT NULL CHECK(version=1),
 UNIQUE(id,tenant_id,workspace_id,environment,app_env),UNIQUE(topic,source_id,sequence),FOREIGN KEY(topic,source_id) REFERENCES developer_webhook_sources(topic,source_id)
);
CREATE TABLE developer_webhook_deliveries(
 id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL,event_id TEXT NOT NULL,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation BETWEEN 1 AND 1000000000),fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64),
 status TEXT NOT NULL CHECK(status IN('queued','sending','retrying','delivered','failed','unknown','blocked','cancelled')),attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 5,available_at TEXT NOT NULL,lease_token TEXT,lease_until TEXT,last_code TEXT CHECK(last_code IN('HTTP_ACCEPTED','HTTP_REJECTED','HTTP_RETRYABLE','REDIRECT_BLOCKED','TRANSPORT_UNCERTAIN','CONFIG_REQUIRED','CONFIG_CHANGED','EXTERNAL_NOT_AUTHORIZED','SCOPE_WITHDRAWN','LEASE_EXPIRED','PAYLOAD_INVALID')),http_status INTEGER CHECK(http_status BETWEEN 100 AND 599),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
 CHECK(attempts BETWEEN 0 AND max_attempts AND max_attempts BETWEEN 1 AND 20),CHECK((status='sending' AND lease_token IS NOT NULL AND lease_until IS NOT NULL) OR(status<>'sending' AND lease_token IS NULL AND lease_until IS NULL)),
 UNIQUE(subscription_id,event_id),FOREIGN KEY(subscription_id,tenant_id,workspace_id,environment,app_env) REFERENCES developer_webhook_subscriptions(id,tenant_id,workspace_id,environment,app_env),FOREIGN KEY(event_id,tenant_id,workspace_id,environment,app_env) REFERENCES developer_webhook_events(id,tenant_id,workspace_id,environment,app_env)
);
CREATE INDEX developer_webhook_queue ON developer_webhook_deliveries(environment,app_env,status,available_at,created_at,id);
CREATE TABLE developer_webhook_attempts(
 delivery_id TEXT NOT NULL REFERENCES developer_webhook_deliveries(id),attempt INTEGER NOT NULL CHECK(attempt BETWEEN 1 AND 20),lease_token TEXT NOT NULL UNIQUE,lease_until TEXT NOT NULL,body_sha256 TEXT CHECK(length(body_sha256)=64),outcome TEXT NOT NULL CHECK(outcome IN('sending','accepted','retryable','rejected','unknown','blocked')),error_code TEXT CHECK(error_code IN('HTTP_ACCEPTED','HTTP_REJECTED','HTTP_RETRYABLE','REDIRECT_BLOCKED','TRANSPORT_UNCERTAIN','CONFIG_REQUIRED','CONFIG_CHANGED','EXTERNAL_NOT_AUTHORIZED','SCOPE_WITHDRAWN','LEASE_EXPIRED','PAYLOAD_INVALID')),http_status INTEGER CHECK(http_status BETWEEN 100 AND 599),started_at TEXT NOT NULL,finished_at TEXT,scope_withdrawn INTEGER NOT NULL DEFAULT 0 CHECK(scope_withdrawn IN(0,1)),PRIMARY KEY(delivery_id,attempt),CHECK((outcome='sending' AND finished_at IS NULL) OR(outcome<>'sending' AND finished_at IS NOT NULL))
);
CREATE TABLE developer_webhook_changes(
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,workspace_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,actor_id TEXT REFERENCES users(id),origin TEXT NOT NULL CHECK(origin IN('administrator','application_policy')),subscription_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN('created','configured','test_queued','retry_queued','policy_disabled')),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 1000000000),delivery_id TEXT REFERENCES developer_webhook_deliveries(id),created_at TEXT NOT NULL,
 CHECK((origin='administrator' AND actor_id IS NOT NULL) OR(origin='application_policy' AND actor_id IS NULL)),FOREIGN KEY(subscription_id,tenant_id,workspace_id,environment,app_env) REFERENCES developer_webhook_subscriptions(id,tenant_id,workspace_id,environment,app_env)
);
CREATE TRIGGER developer_webhook_subscription_identity BEFORE UPDATE ON developer_webhook_subscriptions WHEN NEW.id<>OLD.id OR NEW.app_id<>OLD.app_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.environment<>OLD.environment OR NEW.app_env<>OLD.app_env OR NEW.destination_id<>OLD.destination_id OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 BEGIN SELECT RAISE(ABORT,'Webhook subscription identity is immutable');END;
CREATE TRIGGER developer_webhook_subscription_delete BEFORE DELETE ON developer_webhook_subscriptions BEGIN SELECT RAISE(ABORT,'Webhook subscriptions retain audit identity');END;
CREATE TRIGGER developer_webhook_subscription_cancel AFTER UPDATE ON developer_webhook_subscriptions BEGIN
 UPDATE developer_webhook_attempts SET scope_withdrawn=1 WHERE outcome='sending' AND scope_withdrawn=0 AND delivery_id IN(SELECT id FROM developer_webhook_deliveries WHERE subscription_id=NEW.id AND generation<>NEW.version);
 UPDATE developer_webhook_deliveries SET status='cancelled',lease_token=NULL,lease_until=NULL,last_code='SCOPE_WITHDRAWN',updated_at=NEW.updated_at WHERE subscription_id=NEW.id AND generation<>NEW.version AND status NOT IN('delivered','cancelled');
END;
CREATE TRIGGER developer_webhook_application_policy AFTER UPDATE ON developer_apps WHEN NEW.enabled=0 OR NEW.scopes<>OLD.scopes BEGIN
 INSERT INTO developer_webhook_changes SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))),s.tenant_id,s.workspace_id,s.environment,s.app_env,NULL,'application_policy',s.id,'policy_disabled',s.version+1,NULL,NEW.updated_at FROM developer_webhook_subscriptions s WHERE s.app_id=NEW.id AND s.enabled=1;
 UPDATE developer_webhook_subscriptions SET enabled=0,version=version+1,updated_at=NEW.updated_at WHERE app_id=NEW.id AND enabled=1;
END;
CREATE TRIGGER developer_webhook_events_update BEFORE UPDATE ON developer_webhook_events BEGIN SELECT RAISE(ABORT,'Webhook events and changes are immutable');END;
CREATE TRIGGER developer_webhook_events_delete BEFORE DELETE ON developer_webhook_events BEGIN SELECT RAISE(ABORT,'Webhook events and changes are immutable');END;
CREATE TRIGGER developer_webhook_changes_update BEFORE UPDATE ON developer_webhook_changes BEGIN SELECT RAISE(ABORT,'Webhook events and changes are immutable');END;
CREATE TRIGGER developer_webhook_changes_delete BEFORE DELETE ON developer_webhook_changes BEGIN SELECT RAISE(ABORT,'Webhook events and changes are immutable');END;
CREATE TRIGGER developer_webhook_attempt_identity BEFORE UPDATE ON developer_webhook_attempts WHEN OLD.outcome<>'sending' OR NEW.delivery_id<>OLD.delivery_id OR NEW.attempt<>OLD.attempt OR NEW.lease_token<>OLD.lease_token OR NEW.lease_until<>OLD.lease_until OR NEW.started_at<>OLD.started_at OR NEW.scope_withdrawn<OLD.scope_withdrawn OR(OLD.body_sha256 IS NOT NULL AND NEW.body_sha256 IS NOT OLD.body_sha256) BEGIN SELECT RAISE(ABORT,'Webhook attempt receipt is immutable');END;
CREATE TRIGGER developer_webhook_attempt_delete BEFORE DELETE ON developer_webhook_attempts BEGIN SELECT RAISE(ABORT,'Webhook attempts retain receipts');END;
CREATE TRIGGER developer_webhook_delivery_identity BEFORE UPDATE ON developer_webhook_deliveries WHEN NEW.id<>OLD.id OR NEW.subscription_id<>OLD.subscription_id OR NEW.event_id<>OLD.event_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.environment<>OLD.environment OR NEW.app_env<>OLD.app_env OR NEW.generation<>OLD.generation OR NEW.fingerprint<>OLD.fingerprint OR NEW.created_at<>OLD.created_at OR NEW.attempts<OLD.attempts OR(OLD.status IN('delivered','cancelled') AND NEW.status<>OLD.status) BEGIN SELECT RAISE(ABORT,'Webhook delivery identity is immutable');END;
CREATE TRIGGER developer_webhook_delivery_delete BEFORE DELETE ON developer_webhook_deliveries BEGIN SELECT RAISE(ABORT,'Webhook deliveries retain receipts');END;
CREATE TRIGGER developer_webhook_studio_projects_insert AFTER INSERT ON studio_projects BEGIN
 INSERT INTO developer_webhook_sources SELECT 'projects.changed',NEW.id,NEW.tenant_id,NEW.workspace_id,NEW.environment,NEW.app_env,1,lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))) WHERE EXISTS(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='projects.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='projects.read')) ON CONFLICT(topic,source_id) DO UPDATE SET sequence=developer_webhook_sources.sequence+1,last_event_id=excluded.last_event_id;
 INSERT INTO developer_webhook_events SELECT r.last_event_id,r.tenant_id,r.workspace_id,r.environment,r.app_env,r.topic,r.source_id,r.sequence,json_object('version',1,'id',r.last_event_id,'type','projects.changed','occurredAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'sequence',r.sequence,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'environment',r.environment,'appEnv',r.app_env,'data',json_object('id',NEW.id,'name',NEW.name,'purpose',NEW.purpose,'version',NEW.version,'archived',json(CASE WHEN NEW.archived=1 THEN 'true' ELSE 'false' END),'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)),strftime('%Y-%m-%dT%H:%M:%fZ','now'),1 FROM developer_webhook_sources r WHERE r.topic='projects.changed' AND r.source_id=NEW.id AND r.tenant_id=NEW.tenant_id AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.app_env=NEW.app_env AND EXISTS(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='projects.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='projects.read'));
 INSERT INTO developer_webhook_deliveries(id,subscription_id,event_id,tenant_id,workspace_id,environment,app_env,generation,fingerprint,status,attempts,max_attempts,available_at,created_at,updated_at) SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))),s.id,r.last_event_id,s.tenant_id,s.workspace_id,s.environment,s.app_env,s.version,s.fingerprint,'queued',0,5,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM developer_webhook_subscriptions s JOIN developer_webhook_sources r ON r.topic='projects.changed' AND r.source_id=NEW.id AND r.tenant_id=NEW.tenant_id AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.app_env=NEW.app_env WHERE s.id IN(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='projects.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='projects.read'));
END;
