 INSERT INTO developer_webhook_sources SELECT 'exports.changed',NEW.id,NEW.tenant_id,NEW.workspace_id,NEW.environment,NEW.app_env,1,lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))) WHERE EXISTS(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='exports.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='exports.read') AND EXISTS(SELECT 1 FROM studio_projects p WHERE p.id=NEW.project_id AND p.tenant_id=NEW.tenant_id AND p.workspace_id=NEW.workspace_id AND p.environment=NEW.environment AND p.app_env=NEW.app_env)) ON CONFLICT(topic,source_id) DO UPDATE SET sequence=developer_webhook_sources.sequence+1,last_event_id=excluded.last_event_id;
 INSERT INTO developer_webhook_events SELECT r.last_event_id,r.tenant_id,r.workspace_id,r.environment,r.app_env,r.topic,r.source_id,r.sequence,json_object('version',1,'id',r.last_event_id,'type','exports.changed','occurredAt',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'sequence',r.sequence,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'environment',r.environment,'appEnv',r.app_env,'data',json_object('id',NEW.id,'projectId',NEW.project_id,'projectVersion',NEW.project_version,'kind',NEW.kind,'status',NEW.status,'progress',NEW.progress,'createdAt',NEW.created_at,'updatedAt',NEW.updated_at)),strftime('%Y-%m-%dT%H:%M:%fZ','now'),1 FROM developer_webhook_sources r WHERE r.topic='exports.changed' AND r.source_id=NEW.id AND r.tenant_id=NEW.tenant_id AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.app_env=NEW.app_env AND EXISTS(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='exports.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='exports.read') AND EXISTS(SELECT 1 FROM studio_projects p WHERE p.id=NEW.project_id AND p.tenant_id=NEW.tenant_id AND p.workspace_id=NEW.workspace_id AND p.environment=NEW.environment AND p.app_env=NEW.app_env));
 INSERT INTO developer_webhook_deliveries(id,subscription_id,event_id,tenant_id,workspace_id,environment,app_env,generation,fingerprint,status,attempts,max_attempts,available_at,created_at,updated_at) SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))),s.id,r.last_event_id,s.tenant_id,s.workspace_id,s.environment,s.app_env,s.version,s.fingerprint,'queued',0,5,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM developer_webhook_subscriptions s JOIN developer_webhook_sources r ON r.topic='exports.changed' AND r.source_id=NEW.id AND r.tenant_id=NEW.tenant_id AND r.workspace_id=NEW.workspace_id AND r.environment=NEW.environment AND r.app_env=NEW.app_env WHERE s.id IN(SELECT s.id FROM developer_webhook_subscriptions s JOIN developer_apps a ON a.id=s.app_id WHERE s.tenant_id=NEW.tenant_id AND s.workspace_id=NEW.workspace_id AND s.environment=NEW.environment AND s.app_env=NEW.app_env AND s.enabled=1 AND a.enabled=1 AND EXISTS(SELECT 1 FROM json_each(s.topics) WHERE value='exports.changed') AND EXISTS(SELECT 1 FROM json_each(a.scopes) WHERE value='exports.read') AND EXISTS(SELECT 1 FROM studio_projects p WHERE p.id=NEW.project_id AND p.tenant_id=NEW.tenant_id AND p.workspace_id=NEW.workspace_id AND p.environment=NEW.environment AND p.app_env=NEW.app_env));
END;
